import itertools

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing.
    >>> monotonic([1, 2, 4, 20])
    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    for i in itertools.combinations(l, 2):
        if i[0] > i[1]:
            if any(j > k for j, k in zip(l[l.index(i[0])::], l[l.index(i[1])::])):
                return False
            else:
                return True
        elif i[0] < i[1]:
            if any(j < k for j, k in zip(l[l.index(i[0])::], l[l.index(i[1])::])):
                return False
            else:
                return True
    return True
